pub struct WARP<F: Field, P: BundledPESAT<F>, C: LinearCode<F> + Clone, H: MerkleHasher> {
    pub params: WARPParams<F, P, C, H>,
}

impl<F, P, C, H> WARP<F, P, C, H>
where
    F: Field,
    P: Clone + BundledPESAT<F, Config = (usize, usize, usize)>,
    C: LinearCode<F> + Clone,
    H: MerkleHasher<Symbol = Vec<F>>,
{
    pub fn new(config: WARPConfig<F, P>, code: C, p: P, hasher: H) -> WARP<F, P, C, H> {
        Self {
            params: WARPParams {
                _f: PhantomData,
                config,
                code,
                p,
                hasher,
            },
        }
    }
}

impl<F, P, C, H> AccumulationScheme<F, H> for WARP<F, P, C, H>
where
    F: Field + PrimeField + Encoding<[u8]> + Decoding<[u8]> + NargDeserialize + NargSerialize,
    P: Clone + BundledPESAT<F, Constraints = R1CSConstraints<F>, Config = (usize, usize, usize)>,
    C: LinearCode<F> + Clone,
    H: MerkleHasher<Symbol = Vec<F>>,
    H::Digest: Encoding<[u8]> + Decoding<[u8]> + NargSerialize + NargDeserialize + Clone + Eq,
{
    type Index = P;
    type ProverKey = WARPProverKey<P>;
    type VerifierKey = WARPVerifierKey;
    type Instances = Vec<Vec<F>>;
    type Witnesses = Vec<Vec<F>>;

    fn index(
        prover_state: &mut ProverState,
        index: Self::Index,
    ) -> spongefish::VerificationResult<(Self::ProverKey, Self::VerifierKey)> {
        let (m, n, k) = index.config();
        prover_state.public_message(&index.description());
        prover_state.prover_message(&F::from(m as u32));
        prover_state.prover_message(&F::from(n as u32));
        prover_state.prover_message(&F::from(k as u32));
        Ok((
            WARPProverKey {
                index,
                m,
                n,
                k,
            },
            WARPVerifierKey { m, n, k },
        ))
    }

    #[tracing::instrument(name = "warp.prove", skip_all)]
    fn prove(
        &self,
        pk: Self::ProverKey,
        prover_state: &mut ProverState,
        witnesses: Self::Witnesses,
        instances: Self::Instances,
        acc_instance: AccumulatorInstance<F, H>,
        acc_witness: AccumulatorWitness<F, H>,
    ) -> ProveResult<F, H> {
        if instances.len() < 2 {
            return Err(ProverError::InsufficientInstances {
                got: instances.len(),
            });
        }
        if witnesses.len() != instances.len() {
            return Err(ProverError::InstanceWitnessLengthMismatch {
                instances: instances.len(),
                witnesses: witnesses.len(),
            });
        }
        if acc_witness.td.len() != acc_instance.rt.len() {
            return Err(ProverError::AccumulatorShapeMismatch {
                instances: acc_instance.rt.len(),
                roots: acc_witness.td.len(),
            });
        }

        let (l1, l) = (self.params.config.l1, self.params.config.l);
        let l2 = l - l1;
        if !l.is_power_of_two() {
            return Err(ProverError::ConfigParameterInvalid {
                reason: format!("config.l = {l} is not a power of two"),
            });
        }

        #[allow(non_snake_case)]
        let (M, N, k) = (pk.m, pk.n, pk.k);
        let (log_m, log_l) = (log2(M) as usize, log2(l) as usize);
        let n = self.params.code.code_len();
        let log_n = log2(n) as usize;

        if instances[0].len() != N - k {
            return Err(ProverError::InstanceLengthMismatch {
                expected: N - k,
                got: instances[0].len(),
            });
        }
        absorb_instances(prover_state, &instances);
        acc_instance.absorb_into(prover_state);

        // Destructure acc_witness. Codewords live inside td[i].codewords();
        // we extract the single codeword per accumulator entry into acc_fs
        // for use by twin_constraint.
        let AccumulatorWitness {
            td: acc_tds,
            w: acc_ws,
        } = acc_witness;
        let acc_fs: Vec<Vec<F>> = acc_tds.iter().map(|td| td.codewords()[0].clone()).collect();

        // The pipeline holds the five phase instances built once with
        // their setup borrows (code, hasher, r1cs, bundled_pesat). The
        // orchestrator below drives them through the WARP protocol —
        // the phase calls and inter-phase glue stay visible here as a
        // protocol map. (`pipeline.prove(...)` is also available as a
        // single-call entry point used by tests/composition_demo.rs.)
        let pipeline = WarpPipeline::new(
            &self.params.code,
            &self.params.hasher,
            self.params.p.constraints(),
            &self.params.p,
            n,
        );

        // ── Phase 2: PESAT — encode witnesses, commit, derive τ ──────
        let (pesat_red, _pesat_proof, pesat_red_wit) = pipeline.pesat.prove(
            prover_state,
            &PesatStatement { l1, log_m },
            &PesatWitness {
                witnesses: &witnesses,
            },
            &(),
        )?;

        // ── Phase 3a: twin-constraint sumcheck ──────────────────────
        let (tc_red, _tc_proof, tc_red_wit) = pipeline.twin_constraint.prove(
            prover_state,
            &TwinConstraintStatement {
                acc_instance,
                l1_mus: pesat_red.mus.clone(),
                l1_taus: pesat_red.taus.clone(),
                log_l,
                log_m,
                log_n,
            },
            &TwinConstraintWitness {
                acc_witness_w: &acc_ws,
                instances: &instances,
                witnesses: &witnesses,
            },
            &TwinConstraintProverInputs {
                fresh_codewords: &pesat_red_wit.codewords,
                acc_codewords: &acc_fs,
            },
        )?;

        // ── Phase 3b: bundled η, ν₀, new commitment, absorb ──────────
        let beta_eq_evals = compute_hypercube_eq_evals(log_m, &tc_red.beta_tau);
        let eta = self
            .params
            .p
            .evaluate_bundled(&beta_eq_evals, &tc_red_wit.z)
            .map_err(|_| ProverError::SpongeFish)?;
        let nu_0 = tc_red_wit.f.query_at_point(&tc_red.zeta_0);

        let (new_x, new_w) = tc_red_wit.z.split_at(N - k);
        let new_x = new_x.to_vec();
        let new_w = new_w.to_vec();
        let new_beta = (vec![tc_red.beta_tau.clone()], vec![new_x]);

        let td_new = {
            let _s = tracing::info_span!("warp.commit_new_oracle").entered();
            count_ops!(MerkleTreeBuilds);
            let scheme = warp_scheme::<H, F>(self.params.hasher.clone(), n);
            scheme.commit(&[tc_red_wit.f.evals().to_vec()])
        };
        prover_state.prover_message(td_new.root());
        prover_state.prover_message(&eta);
        prover_state.prover_message(&nu_0);

        // ── Phase 3c: OOD ──────────────────────────────────────────
        let (ood_red, _, _) = pipeline.ood.prove(
            prover_state,
            &OodStatement {
                s: self.params.config.s,
                log_n,
            },
            &(),
            &OodProverInputs {
                oracle: &tc_red_wit.f,
            },
        )?;

        // ── Phase 3c → 3d glue: sample shift queries ───────────────
        let queries = QueryIndices::<F>::sample(prover_state, log_n, self.params.config.t);

        // ── Phase 3d: batching sumcheck (DAG fan-in: tc.zeta_0 +
        // ood.samples_flat + queries.evaluation_points) ─────────────
        let (batching_red, _, batching_red_wit) = pipeline.batching.prove(
            prover_state,
            &BatchingStatement::from_phase_outputs(
                tc_red.zeta_0.clone(),
                &ood_red.samples_flat,
                &queries.evaluation_points,
                self.params.config.s,
                self.params.config.t,
                log_n,
            ),
            &(),
            &BatchingProverInputs {
                oracle: &tc_red_wit.f,
            },
        )?;

        // ── Phase 3e: proximity (shift-query openings) ─────────────
        let (_, prox, _) = pipeline.proximity.prove(
            prover_state,
            &ProximityStatement {
                queries: queries.clone(),
                l2,
                t: self.params.config.t,
                n,
            },
            &(),
            &ProximityProverInputs {
                td_0: &pesat_red_wit.td_0,
                acc_td: &acc_tds,
            },
        )?;

        // ── Assemble new accumulator state and proof ───────────────
        let mut nus = Vec::with_capacity(1 + self.params.config.s);
        nus.push(nu_0);
        nus.extend(ood_red.answers);

        let new_acc_instance = AccumulatorInstance {
            rt: vec![td_new.root().clone()],
            alpha: vec![batching_red.alpha],
            mu: vec![batching_red_wit.mu],
            beta: new_beta,
            eta: vec![eta],
        };
        let new_acc_witness = AccumulatorWitness {
            td: vec![td_new],
            w: vec![new_w],
        };
        let proof = WARPProof {
            rt_0: pesat_red_wit.td_0.root().clone(),
            mu_i: pesat_red.mus,
            nu_0,
            nu_i: nus,
            auth_0: prox.auth_0,
            auth_j: prox.auth_j,
            shift_query_answers: prox.shift_query_answers,
        };

        Ok(((new_acc_instance, new_acc_witness), proof))
    }

    fn verify<'a>(
        &self,
        vk: Self::VerifierKey,
        verifier_state: &mut VerifierState<'a>,
        acc_instance: AccumulatorInstance<F, H>,
        proof: WARPProof<F, H>,
    ) -> Result<(), VerifierError> {
        let (l1, l) = (self.params.config.l1, self.params.config.l);
        let l2 = l - l1;

        #[allow(non_snake_case)]
        let (M, N, k) = (vk.m, vk.n, vk.k);
        let (log_m, log_l) = (log2(M) as usize, log2(l) as usize);
        let n = self.params.code.code_len();
        let log_n = log2(n) as usize;

        // Parse the transcript-side statement (l1 fresh instances + l2
        // accumulated entries). Stays in the orchestrator: it crosses
        // the pipeline/non-pipeline boundary by definition.
        let (l1_xs, parsed_acc) =
            parse_statement::<F, H>(verifier_state, l1, l2, N - k, log_n, log_m)?;

        // Cache prior-accumulator values needed by the post-pipeline
        // (α, β) consistency checks. These cross-reference the prior
        // single-entry `acc_instance` against the pipeline's reduced
        // outputs, so they live outside the pipeline.
        let acc_alpha_first = acc_instance.alpha[0].clone();
        let acc_beta_0_first = acc_instance.beta.0[0].clone();
        let acc_beta_1_first = acc_instance.beta.1[0].clone();
        let acc_mu_first = acc_instance.mu[0];
        let l2_taus = parsed_acc.beta.0.clone();
        let l2_xs = parsed_acc.beta.1.clone();

        // Cache the accumulated roots before `parsed_acc` moves into TC's
        // statement — Proximity needs them for the per-acc Merkle handles.
        let l2_roots = parsed_acc.rt.clone();

        // Pipeline holds the five phase instances. The orchestrator drives
        // them through the WARP verifier protocol below; phase calls and
        // inter-phase glue stay visible here.
        let pipeline = WarpPipeline::new(
            &self.params.code,
            &self.params.hasher,
            self.params.p.constraints(),
            &self.params.p,
            n,
        );

        // ── Phase 2: PESAT::verify ──────────────────────────────────
        let (pesat_red, pesat_v_out) = pipeline.pesat.verify(
            verifier_state,
            &PesatStatement { l1, log_m },
            &(),
        )?;
        let l1_mus = pesat_red.mus;
        let l1_taus = pesat_red.taus;
        let rt_0 = pesat_v_out.rt_0;

        // ── Phase 3a: TwinConstraint::verify ────────────────────────
        let (tc_red, _) = pipeline.twin_constraint.verify(
            verifier_state,
            &TwinConstraintStatement {
                acc_instance: parsed_acc,
                l1_mus,
                l1_taus: l1_taus.clone(),
                log_l,
                log_m,
                log_n,
            },
            &(),
        )?;

        // ── Phase 3b: read td_digest, η, ν₀; discharge deferred check
        let _td_digest: H::Digest = verifier_state.prover_message()?;
        let eta: F = verifier_state.prover_message()?;
        let nu_0: F = verifier_state.prover_message()?;
        tc_red.deferred.discharge(&tc_red.gamma, nu_0, eta)?;

        // ── Phase 3c: OOD::verify ───────────────────────────────────
        let (ood_red, _) = pipeline.ood.verify(
            verifier_state,
            &OodStatement {
                s: self.params.config.s,
                log_n,
            },
            &(),
        )?;

        // ── Phase 3c → 3d glue: sample shift queries, arity checks,
        // build IndexedOracle handles for fresh + accumulated commits
        let n_shift_query_bytes = (self.params.config.t * log_n).div_ceil(8);
        let bytes_shift_queries: Vec<u8> = (0..n_shift_query_bytes)
            .map(|_| verifier_state.verifier_message::<[u8; 1]>()[0])
            .collect();
        let queries: QueryIndices<F> =
            QueryIndices::from_squeezed_bytes(&bytes_shift_queries, log_n, self.params.config.t);

        (proof.shift_query_answers.len() == self.params.config.t)
            .then_some(())
            .ok_or(VerifierError::NumShiftQueries)?;
        (proof.auth_j.len() == l2)
            .then_some(())
            .ok_or(VerifierError::NumL2Instances)?;

        let mut indexed: Vec<(usize, usize)> = queries
            .leaf_positions
            .iter()
            .copied()
            .enumerate()
            .map(|(row, pos)| (pos, row))
            .collect();
        indexed.sort_by_key(|&(pos, _)| pos);
        indexed.dedup_by_key(|&mut (pos, _)| pos);
        let sorted_unique: Vec<usize> = indexed.iter().map(|&(p, _)| p).collect();
        let row_indices: Vec<usize> = indexed.iter().map(|&(_, r)| r).collect();

        let fresh_values: Vec<Vec<F>> = row_indices
            .iter()
            .map(|&r| proof.shift_query_answers[r][l2..].to_vec())
            .collect();
        let fresh_handle = MerkleIndexedOracle::new(
            warp_scheme::<H, F>(self.params.hasher.clone(), n),
            &rt_0,
            &proof.auth_0,
            sorted_unique.clone(),
            fresh_values,
        );

        let acc_handles: Vec<MerkleIndexedOracle<F, H>> = (0..l2)
            .map(|j| {
                let acc_values: Vec<Vec<F>> = row_indices
                    .iter()
                    .map(|&r| vec![proof.shift_query_answers[r][j]])
                    .collect();
                MerkleIndexedOracle::new(
                    warp_scheme::<H, F>(self.params.hasher.clone(), n),
                    &l2_roots[j],
                    &proof.auth_j[j],
                    sorted_unique.clone(),
                    acc_values,
                )
            })
            .collect();

        // ── Phase 3e: Proximity::verify ─────────────────────────────
        pipeline.proximity.verify(
            verifier_state,
            &ProximityStatement {
                queries: queries.clone(),
                l2,
                t: self.params.config.t,
                n,
            },
            &ProximityVerifierInputs {
                fresh: &fresh_handle,
                acc: &acc_handles,
                _f: PhantomData,
            },
        )?;

        // ── Recompute ν vector from shift answers ──────────────────
        let gamma_eq_evals = compute_hypercube_eq_evals(log_l, &tc_red.gamma);
        let mut nus = Vec::with_capacity(1 + self.params.config.s + self.params.config.t);
        nus.push(nu_0);
        nus.extend(ood_red.answers);
        for v_jk in proof.shift_query_answers.iter() {
            let nu_st = v_jk
                .iter()
                .zip(&gamma_eq_evals)
                .fold(F::zero(), |acc, (v, eq)| acc + *eq * *v);
            nus.push(nu_st);
        }

        // ── Phase 3d: Batching::verify ─────────────────────────────
        let (batching_red, _) = pipeline.batching.verify(
            verifier_state,
            &BatchingStatement::from_phase_outputs(
                tc_red.zeta_0.clone(),
                &ood_red.samples_flat,
                &queries.evaluation_points,
                self.params.config.s,
                self.params.config.t,
                log_n,
            ),
            &BatchingVerifierInputs {
                nus,
                acc_mu: acc_mu_first,
            },
        )?;

        // ── Post-pipeline accumulator consistency ──────────────────
        (acc_alpha_first == batching_red.alpha)
            .then_some(())
            .ok_or(VerifierError::CodeEvaluationPoint)?;

        let betas = l2_taus
            .into_iter()
            .chain(l1_taus)
            .zip(l2_xs.into_iter().chain(l1_xs))
            .map(|(tau_i, x)| concat_slices(&tau_i, &x))
            .collect::<Vec<Vec<F>>>();
        let beta = scale_and_sum(&betas, &gamma_eq_evals);
        let expected_beta = concat_slices(&acc_beta_0_first, &acc_beta_1_first);
        (expected_beta == beta)
            .then_some(())
            .ok_or(VerifierError::CircuitEvaluationPoint)?;

        Ok(())
    }

    fn decide(
        &self,
        acc_witness: AccumulatorWitness<F, H>,
        acc_instance: AccumulatorInstance<F, H>,
    ) -> Result<(), WARPError> {
        // The accumulator witness's codeword is td[0].codewords()[0].
        let acc_codeword = &acc_witness.td[0].codewords()[0];

        // Re-encode the witness; check codeword match.
        let computed_f = self.params.code.encode(&acc_witness.w[0]);
        (acc_codeword == &computed_f).then_some(()).ok_or(DeciderError::EncodedWitness)?;

        // Re-commit and check root.
        let scheme = warp_scheme::<H, F>(self.params.hasher.clone(), self.params.code.code_len());
        let recomputed = scheme.commit(std::slice::from_ref(&computed_f));
        (acc_instance.rt[0] == *recomputed.root()).then_some(()).ok_or(DeciderError::MerkleRoot)?;
        (acc_witness.td[0].root() == recomputed.root()).then_some(()).ok_or(DeciderError::MerkleTrapDoor)?;

        // MLE evaluation check.
        let f_hat = DenseMultilinearExtension::from_evaluations_slice(
            log2(self.params.code.code_len()) as usize,
            acc_codeword,
        );
        (f_hat.evaluate(&acc_instance.alpha[0]) == acc_instance.mu[0])
            .then_some(()).ok_or(DeciderError::MLExtensionEvaluation)?;

        // Bundled-evaluation check.
        let tau = &acc_instance.beta.0[0];
        let tau_zero_evader = compute_hypercube_eq_evals(tau.len(), tau);
        let mut z = acc_instance.beta.1[0].clone();
        z.extend(acc_witness.w[0].clone());
        let computed_eta = self
            .params
            .p
            .evaluate_bundled(&tau_zero_evader, &z)
            .unwrap();
        (computed_eta == acc_instance.eta[0]).then_some(()).ok_or(DeciderError::BundledEvaluation)?;

        Ok(())
    }
}
